import { splitFrames } from './split-frames.mjs';

function validateDelimiter(delimiter) {
  if (typeof delimiter !== 'string' || delimiter.length === 0) {
    throw new TypeError('delimiter must be a nonempty string');
  }
}

function properPrefixSuffixLength(text, delimiter) {
  const limit = Math.min(text.length, delimiter.length - 1);
  for (let n = limit; n > 0; n--) {
    if (delimiter.startsWith(text.slice(text.length - n))) {
      return n;
    }
  }
  return 0;
}

function assertWithinBuffer(length, maxBuffer) {
  if (length > maxBuffer) {
    throw new RangeError('frame exceeds maxBuffer');
  }
}

export function createFramer({ delimiter = '\r\n', maxBuffer = 1024 } = {}) {
  validateDelimiter(delimiter);
  if (!Number.isFinite(maxBuffer) || !Number.isInteger(maxBuffer) || maxBuffer < 0) {
    throw new RangeError('maxBuffer must be a finite nonnegative integer');
  }

  let pending = '';
  let closed = false;

  return {
    push(chunk) {
      if (closed) {
        throw new Error('framer is closed');
      }
      if (typeof chunk !== 'string') {
        throw new TypeError('chunk must be a string');
      }
      if (chunk.length === 0) {
        const suffix = properPrefixSuffixLength(pending, delimiter);
        assertWithinBuffer(pending.length - suffix, maxBuffer);
        return [];
      }
      pending += chunk;
      const { frames, rest } = splitFrames(pending, delimiter);
      for (const frame of frames) {
        assertWithinBuffer(frame.length, maxBuffer);
      }
      pending = rest;
      const suffix = properPrefixSuffixLength(pending, delimiter);
      assertWithinBuffer(pending.length - suffix, maxBuffer);
      return frames;
    },
    finish() {
      if (closed) {
        throw new Error('framer is closed');
      }
      closed = true;
      if (pending.length === 0) {
        return [];
      }
      const frame = pending;
      pending = '';
      assertWithinBuffer(frame.length, maxBuffer);
      return [frame];
    },
  };
}

